{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Godot Data-Driven Config Field Spec",
  "description": "One spec describes one <Name>Data class. Feed to scaffold.py.",
  "type": "object",
  "required": ["name", "fields"],
  "properties": {
    "name": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*$",
      "description": "snake_case category name, e.g. 'weapon', 'enemy'. Will produce class_name <Name>Data."
    },
    "display": {
      "type": "string",
      "description": "Human-readable category name. Default = Title Case of `name`."
    },
    "base_class": {
      "type": "string",
      "default": "Resource",
      "description": "Rarely changed. Resource is right 99% of the time."
    },
    "default_id": {
      "type": "string",
      "description": "Default entry id, e.g. 'default_weapon'. Default = 'default_' + name."
    },
    "fields": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/definitions/field" }
    },
    "validators": {
      "type": "array",
      "items": {
        "type": "string",
        "description": "Simple GDScript boolean expression referring to fields, e.g. 'bullet_speed > 0'. Evaluated per-entry in DataManager.validate()."
      }
    }
  },
  "definitions": {
    "field": {
      "type": "object",
      "required": ["key", "type"],
      "properties": {
        "key": {
          "type": "string",
          "pattern": "^[a-z_][a-z0-9_]*$"
        },
        "type": {
          "type": "string",
          "enum": [
            "bool", "int", "float", "String", "StringName",
            "Vector2", "Vector3", "Color", "NodePath",
            "PackedScene", "Texture2D", "AudioStream", "Resource",
            "Array", "Dictionary"
          ]
        },
        "default": {
          "description": "Literal GDScript value, printed as-is. E.g. 20.0, \"\\\"Pistol\\\"\", \"&\\\"\\\"\", \"Vector3.ZERO\"."
        },
        "range": {
          "type": "array",
          "description": "[min, max, step] — produces @export_range. Only for int/float.",
          "minItems": 2,
          "maxItems": 3,
          "items": { "type": "number" }
        },
        "multiline": {
          "type": "boolean",
          "description": "For String only. Produces @export_multiline."
        },
        "group": {
          "type": "string",
          "description": "Inspector group. Consecutive fields with same group are merged under @export_group."
        },
        "doc": {
          "type": "string",
          "description": "GDScript doc comment above the field."
        },
        "required": {
          "type": "boolean",
          "description": "Reserved: validator will check not-empty/not-null."
        }
      }
    }
  }
}
